import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceTheme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  value?: AppearanceSettings;
  defaultValue?: AppearanceSettings;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const THEME_LABELS: Record<AppearanceTheme, string> = {
  light: 'Светлая тема',
  dark: 'Тёмная тема',
  system: 'Системная тема',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces', meta: 'акцидентный' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'моноширинный' },
];

const FALLBACK: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'sans',
};

export default function AppearanceSettingsScreen({
  value,
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [internal, setInternal] = useState<AppearanceSettings>(
    defaultValue ?? FALLBACK,
  );
  const settings = value ?? internal;

  const update = useCallback(
    (patch: Partial<AppearanceSettings>) => {
      const next = { ...settings, ...patch };
      if (value === undefined) setInternal(next);
      onChange?.(next);
    },
    [settings, value, onChange],
  );

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '24px',
        maxWidth: '560px',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap',
        }}
      >
        <h2
          style={{
            margin: 0,
            fontFamily: 'var(--jx-font-display)',
            fontSize: '20px',
            lineHeight: 1.3,
          }}
        >
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {THEME_LABELS[settings.theme]}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <span style={{ fontSize: '13px' }}>Тема оформления</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(theme) => update({ theme: theme as AppearanceTheme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.fontFamily}
        onValueChange={(fontFamily) => update({ fontFamily })}
      />
    </section>
  );
}

